style.css:
@-moz-document domain("chefkoch.de") {
/* ====================================================================
     Palette via design-system custom properties
     Chefkoch's frontend is driven by --ck-color-* tokens on :root.
     Retheming these recolors most surfaces/text/borders site-wide; the
     element rules below mop up everything that is hardcoded.
     ==================================================================== */
  :root {
    color-scheme: dark !important;
    --ck-color-bg-primary: #14181d !important;   /* page surface (#f6f7f4) */
    --ck-color-bg-header:  #0d1117 !important;    /* header band (#e2ece3) */
    --ck-color-text-primary: #e6edf3 !important;  /* body text (#212018) */
    --ck-color-border: #262c33 !important;        /* hairlines (#ddd) */
    /* keep the brand green – it stays readable on dark */
    --ck-color-brand-green: #4cae5e !important;
    --ck-color-brand-green-dark: #3fa052 !important;
  }

  /* ====================================================================
     Base surfaces  (the "w-" shell + "ds-" content container)
     ==================================================================== */
  html, body {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }
  body, main, .ds-container, .ds-bg-container,
  .w-header, .w-header.w-scope, .w-header__menu, .w-main-menu, .w-flyout,
  .w-mobile-menu, .w-funke-banner, .w-footer, .w-footer.w-scope, #content,
  .content, .recipe, .ds-page {
    background-color: #14181d !important;
  }
  /* the CMS "stage" wave (magazine overview etc.) ships as a cream #F6F7F4
     SVG background-image on body that paints over our dark bg and washes
     out the light heading — drop the decorative image on dark */
  body.ds-cms-bg-home, body[class*="ds-cms-bg"] {
    background-image: none !important;
  }

  /* Soften every default light border to a subtle dark line */
  * { border-color: #262c33 !important; }

  /* ====================================================================
     Header / global nav  ("w-" shell)
     ==================================================================== */
  .w-header, .w-header.w-scope, .w-funke-banner {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-bottom: 1px solid #262c33 !important;
  }
  /* backdrop pseudo behind the sticky header ships solid white and peeks
     out as a sliver below the nav — recolor it to the header bg */
  #w-header::before, .w-header::before, .w-header.w-scope::before {
    background-color: #0d1117 !important;
  }
  .w-header__menu, .w-main-menu, .w-flyout, .w-mobile-menu, .w-mobile-menu-head {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }
  .w-header a, .w-main-menu a, .w-flyout a, .w-funke-banner,
  .w-header__actions, .w-menu-button, .ds-tab-nav__link {
    color: #e6edf3 !important;
  }
  .w-header a:hover, .w-main-menu a:hover, .ds-tab-nav__link:hover { color: #ffffff !important; }
  /* "Eine Marke von FUNKE" wordmark: its <svg> carries its own color:#000 and
     the paths fill with currentColor -> pure black on the dark banner */
  .w-funke-banner__link, .w-funke-banner__link svg { color: #c4cdd6 !important; }
  .w-funke-banner__link svg path { fill: currentColor !important; }
  /* logo glyphs (green hat + dark wordmark) -> keep hat green, lift letters */
  [data-testid="logo-hat"], [data-testid="logo-hat"] path { fill: #4cae5e !important; }
  [data-testid="logo-letters"], [data-testid="logo-letters"] path { fill: #e6edf3 !important; }
  /* header search field */
  .w-header__search, .w-header__search input, .w-header__search form {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .w-header__search input::placeholder { color: #8b949e !important; }
  .w-header__search svg, .w-header svg { fill: #c4cdd6 !important; }
  /* The header search is now a <search-input> web component whose shadow root
     hardcodes a #fff pill (.ds-search-bar__control) — no selector can reach it.
     Only inherited properties cross the shadow boundary, so:
       - `color` is reset to the site's original ink, otherwise our light body
         colour lands on the component's white fullscreen search overlay (which
         lives in the TOP LAYER and therefore ignores the filter below) and the
         suggestion list renders white-on-white;
       - the collapsed pill in the header is darkened with a hue-preserving
         invert on the host (top-layer overlay is unaffected by it).
     The wrapper loses its own fill so no light plate shows around the pill. */
  .w-header__search { background-color: transparent !important; }
  search-input {
    color: #212018 !important;
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* PLUS flyout / menu panels */
  .w-flyout__col, .w-flyout__teaser-link, .w-flyout__menu-btn {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }

  /* ====================================================================
     Typography (shared)
     ==================================================================== */
  h1, h2, h3, h4, h5, h6,
  .ds-h1, .ds-h2, .ds-h3, .ds-h4,
  .ds-heading, .ds-text-blackberry, .ds-text-semi-bold {
    color: #e6edf3 !important;
  }
  p, li, dd, dt, span, td, th, label, figcaption, time, small, blockquote,
  .ds-text-sans, .ds-text-basmati, .recipe-text {
    color: #c4cdd6 !important;
  }
  /* secondary / caption / "olive" greys (#595852, #807f78) are too dark on
     a dark surface — lift them to a readable muted grey */
  .ds-text-caption, .ds-text-olive-medium, .ds-text-olive,
  .ds-text-secondary, .ds-text-muted, .ds-recipe-card__description,
  .ds-collection-card__info-value, .ds-collection-card__info-label,
  .ds-collection-card__date, small.ds-text-caption,
  /* comment / author meta timestamp ("vor 2 Stunden") ships as a dark
     olive #595852 that fails contrast on the dark card -> muted grey */
  .ds-author__caption, .ds-author__meta .ds-author__caption {
    color: #9aa5af !important;
  }
  /* monochrome glyph-font icons default to a dark olive — lift to muted grey */
  i.chefkoch-icons, .chefkoch-icons,
  .ds-collection-card__info-icon, .recipe-meta-property-group__icon {
    color: #9aa5af !important;
  }

  /* ---- Links: keep the Chefkoch green, lifted for dark contrast ---- */
  a, .ds-text-link, a.ds-text-link {
    color: #4cae5e !important;
  }
  a:hover, .ds-text-link:hover { color: #6fd382 !important; }
  /* breadcrumbs */
  .ds-breadcrumb, .ds-breadcrumb__item, .ds-breadcrumb__item--current { color: #8b949e !important; }
  .ds-breadcrumb__link { color: #c4cdd6 !important; }
  .ds-breadcrumb__link:hover { color: #4cae5e !important; }

  /* ====================================================================
     Recipe page: ingredients, quantity, nutrition, meta, steps
     ==================================================================== */
  /* ingredients table */
  .ds-ingredients-table,
  .ds-ingredients-table__tr,
  .recipe-ingredients { background-color: transparent !important; color: #c4cdd6 !important; }
  .ds-ingredients-table__th,
  .ds-ingredients-table__head,
  .ds-ingredients-table__headline {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-ingredients-table__td,
  .ds-ingredients-table__td--first,
  .ds-ingredients-table__ingredient,
  .ds-ingredients-table__ingredient-name {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* PLUS paywall fade over long ingredient lists is a white gradient
     (::before) — recolor it to fade into the dark page bg instead */
  .recipe-ingredients--fadeout::before,
  .recipe-ingredients--fadeout::after,
  [class*="fadeout"]::before, [class*="fadeout"]::after {
    background-image: linear-gradient(rgba(20,24,29,0), #14181d) !important;
  }

  /* portion / quantity control */
  .ds-quantity-control,
  .ds-quantity-control__input-wrap,
  .ds-quantity-control__input {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-quantity-control__up, .ds-quantity-control__down,
  .ds-quantity-control__label, .ds-quantity-control__amount { color: #e6edf3 !important; }

  /* nutrition block */
  .ds-nutrition, .ds-nutrition__layout { background-color: transparent !important; }
  .ds-nutrition__cell {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-nutrition__title, .ds-nutrition__value, .ds-nutrition__labels { color: #e6edf3 !important; }
  .ds-nutrition__icon { fill: #c4cdd6 !important; }

  /* recipe meta (prep time, difficulty, calories) */
  .recipe-meta-property-group,
  .recipe-meta-property-group__cell { background-color: transparent !important; }
  .recipe-meta-property-group__title, .recipe-meta-property-group__value { color: #e6edf3 !important; }
  .recipe-meta-property-group__detail, .recipe-meta-property-group__labels { color: #9aa5af !important; }
  .recipe-meta-property__link { color: #4cae5e !important; }

  /* ====================================================================
     Cards, teasers, editorial tiles (home + search + recipe sidebar)
     ==================================================================== */
  .ds-teaser-link, .ds-editorial-card, .ds-subscription-card,
  .ds-slider-image, .ds-card, .ds-recipe-card, .rsel-recipe,
  .ds-rounded-2, .ds-rounded-s-6, .ds-bg-blackberry,
  .ds-collection-card, .ds-collection-card__infos, .ds-category-card,
  .ds-category-card--garlic, .ds-profile-card, .ds-profile-card__bottom,
  .recipesOfTheDay, .recipe-of-the-day, .ds-bg-garlic {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .ds-teaser-link__headline, .ds-editorial-card__headline,
  .ds-collection-card__headline, .ds-category-card__headline,
  .ds-category-card__name, .ds-collection-card__title,
  .ds-slider-image__info, .ds-slider-image__info-link { color: #e6edf3 !important; }
  .ds-teaser-link:hover, .ds-editorial-card:hover, .rsel-recipe:hover,
  .ds-collection-card:hover, .ds-category-card:hover { background-color: #21262d !important; }
  /* the trend / category tiles each carry their own pastel (yellow, green, pink,
     blue, cream) that names the category. Collapsing all five to one grey erased
     that signal — keep every hue, darkened so the white tile label still reads. */
  .ds-category-card--mirabelle { background-color: #6b5410 !important; }
  .ds-category-card--broccoli { background-color: #2f5c3b !important; }
  .ds-category-card--watermelon { background-color: #6e3034 !important; }
  .ds-category-card--blueberry { background-color: #22485a !important; }
  .ds-category-card--garlic { background-color: #1c2128 !important; }
  .ds-category-card--mirabelle:hover { background-color: #7d6314 !important; }
  .ds-category-card--broccoli:hover { background-color: #386c46 !important; }
  .ds-category-card--watermelon:hover { background-color: #813940 !important; }
  .ds-category-card--blueberry:hover { background-color: #2a5569 !important; }
  .ds-category-card--garlic:hover { background-color: #21262d !important; }
  /* horizontal sliders fade their edges with a WHITE gradient painted by a
     ::before/::after background-IMAGE — no element-background scan can see it,
     and it renders as a bright wash over the last tile of every carousel */
  .ds-h-scroll-wrap--gradient-left::before {
    background-image: linear-gradient(90deg, #14181d, #14181d 50%, rgba(20, 24, 29, 0)) !important;
  }
  .ds-h-scroll-wrap--gradient-right::after {
    background-image: linear-gradient(270deg, #14181d, #14181d 50%, rgba(20, 24, 29, 0)) !important;
  }
  /* image-wrap skeleton placeholders (light-green #e2ece3 behind thumbnails) */
  .ds-teaser-link__image-wrap, .ds-editorial-card__image-wrap,
  .ds-slider-image__image-wrap, .ds-recipe-card__image-wrap,
  .ds-collection-card__image-wrap, .ds-category-card__image-wrap,
  [class*="__image-wrap"] { background-color: #1c2128 !important; }
  /* the category tile's image-wrap covers the WHOLE tile and its artwork is a
     transparent PNG, so filling it hides the per-category tint set below */
  .ds-category-card__image-wrap { background-color: transparent !important; }
  /* profile-card top: a cream #f6f7f4 plate painted by ::before sits behind the
     circular avatar/brand-logo image (home "Profis", magazine "Rezepte von
     Profis"). The avatar img keeps its own circle, so darken just the plate. */
  .ds-profile-card__top { background-color: #1c2128 !important; }
  .ds-profile-card__top::before, .ds-profile-card__top::after {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  /* hero teaser "shape": the decorative wave at the bottom of the .ds-main-slide
     is an SVG path filled white to blend into the light page — on dark it reads
     as a bright wave, so fill it with the page bg to vanish into the surface */
  .ds-main-slide__shape svg path, .ds-main-slide__shape path { fill: #14181d !important; }
  /* "recipe of the day" inner highlight panel uses the light-green tint */
  .recipesOfTheDay .ds-rounded-4, .recipesOfTheDay [class*="ds-pv-"],
  .recipesOfTheDay > div { background-color: transparent !important; }
  /* PLUS subscription cards keep an elevated tint (incl. inner panels) */
  .ds-subscription-card--plus,
  .ds-subscription-card__head, .ds-subscription-card__body,
  .ds-subscription-card__footer { background-color: #20222a !important; }
  .ds-subscription-card__head *, .ds-subscription-card__body *,
  .ds-subscription-card__footer * { color: #e6edf3 !important; }

  /* newsletter / promo bands painted in the light-green header tint (#e2ece3) */
  .ds-newsletter, .ds-newsletter-box, .newsletter, .newsletter-box,
  .ds-bg-mint, .ds-bg-green-light, [class*="newsletter"],
  [class*="__newsletter"], .ds-promo-band, .ds-cta-band {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  [class*="newsletter"] h2, [class*="newsletter"] h3,
  [class*="newsletter"] p, [class*="newsletter"] span { color: #e6edf3 !important; }

  /* video "play" badge: white circle behind the glyph -> dark translucent */
  .ds-play-badge, .ds-card-badge--play, [class*="play-badge"] {
    background-color: rgba(13,17,23,0.72) !important;
  }
  .ds-play-badge__icon, [class*="play-badge"] i, [class*="play-badge"] svg {
    color: #ffffff !important; fill: #ffffff !important;
  }

  /* author chips */
  .ds-author, .ds-author__meta { background-color: transparent !important; }
  .ds-author__name, .ds-author__name-prefix { color: #c4cdd6 !important; }
  .ds-author__avatar { background-color: #1c2128 !important; }
  /* card / sidebar author labels keep the site "blackberry" dark text on the
     dark card -> force a high-specificity light override that wins */
  .ds-card .ds-author__name, .ds-recipe-card .ds-author__name,
  .ds-teaser-link .ds-author__name, .ds-collection-card .ds-author__name,
  .ds-author .ds-author__name, .ds-author .ds-author__name-prefix,
  .ds-author__name.ds-text-blackberry, .ds-author__name-prefix.ds-text-blackberry,
  [class*="author"] .ds-text-blackberry, .ds-author [class*="name"] {
    color: #c4cdd6 !important;
  }

  /* ====================================================================
     Recipe COMMENTS — light comment cards on the dark page
     The broad p/li/span/div text rule paints comment bodies near-white,
     so the card MUST become an elevated dark surface to read.
     ==================================================================== */
  .ds-comment, .ds-comment--answers-expanded, .ds-comment__answers,
  .ds-comment__body, .ds-comment__content, .ds-comment__main,
  [class*="ds-comment"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-comment__text, .ds-comment__body, .ds-comment__content,
  .ds-comment p, .ds-comment span, .ds-comment li {
    color: #c4cdd6 !important;
  }
  .ds-comment__author, .ds-comment__author-name { color: #e6edf3 !important; }
  .ds-comment__date, .ds-comment__meta { color: #9aa5af !important; }

  /* ====================================================================
     Recipe AUTHOR-BOX — light cream band
     ==================================================================== */
  .author-box, .author-box__content, .author-box__inner,
  [class*="author-box"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .author-box, .author-box *, [class*="author-box"] * { color: #c4cdd6 !important; }
  .author-box h1, .author-box h2, .author-box h3,
  .author-box__name, .author-box__title { color: #e6edf3 !important; }
  .author-box a, [class*="author-box"] a { color: #4cae5e !important; }

  /* ====================================================================
     Recipe PREP-TIMES bar (Gesamtzeit / Arbeitszeit / Koch-/Backzeit)
     Light cream band -> elevated dark surface + lift the metric labels.
     ==================================================================== */
  .ds-preparation-times, .ds-preparation-times__main,
  .ds-preparation-times__detail, .ds-preparation-times__item,
  [class*="preparation-times"] {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ds-preparation-times__main, .ds-preparation-times__detail,
  .ds-preparation-times__value, .ds-preparation-times__time,
  [class*="preparation-times"] [class*="value"],
  [class*="preparation-times"] [class*="time"] { color: #e6edf3 !important; }
  .ds-preparation-times__label, .ds-preparation-times__title,
  [class*="preparation-times"] [class*="label"],
  [class*="preparation-times"] [class*="title"] { color: #9aa5af !important; }

  /* ====================================================================
     Recipe STEP-NUMBER badges (the "1,2,3..." prep-step circles)
     Light grey number on light-mint circle -> dark circle + light number.
     ==================================================================== */
  .ds-rounded-6.ds-title-xs, [class*="ds-rounded-6"].ds-title-xs {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ====================================================================
     "CHEFKOCH Check" widget (Kniff / Stolperfalle / "richtig gut")
     Each tip is a cream #f6f7f4 .ck-check__item panel with a white
     circular .ck-check__badge behind the icon — the now-light body text
     washes out on it. Repaint the panel + badge to the dark surface.
     ==================================================================== */
  .ck-check__item {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  .ck-check__badge, .ck-check__badge--tip,
  .ck-check__badge--warning, .ck-check__badge--check {
    background-color: #21262d !important;
  }
  .ck-check__label, .ck-check__text { color: #e6edf3 !important; }
  .ck-check__body, .ck-check__body p { color: #c4cdd6 !important; }
  .ck-check__badge i, .ck-check__badge .chefkoch-icons { color: #9aa5af !important; }
  /* each tip type is identified ONLY by the colour of its glyph: gold bulb =
     Kniff, red triangle = Stolperfalle, green tick = richtig gut. The broad
     icon-font grey collapsed all three into the same badge. */
  .ck-check__badge--tip i, .ck-check__badge--tip .chefkoch-icons { color: #ffcd12 !important; }
  .ck-check__badge--warning i, .ck-check__badge--warning .chefkoch-icons { color: #f0736e !important; }
  .ck-check__badge--check i, .ck-check__badge--check .chefkoch-icons { color: #4cae5e !important; }

  /* recipe-header "TOP-REZEPT" award pill ships the light-green #e2ece3
     header tint with a grey laurel + grey label that wash out on it ->
     elevated dark pill with a light label (a short pill the height-gated
     light-surface audit skips) */
  .editorial-info-card__pill {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .editorial-info-card__pill-label { color: #6fd382 !important; }
  .editorial-info-card__pill .chefkoch-icons,
  .editorial-info-card__pill i { color: #9aa5af !important; }

  /* "Nutze Chefkoch ohne Banner" ad-free link is a dark olive on the dark
     page -> lift to a readable muted grey */
  .ads__adfree-link, [class*="adfree-link"] { color: #9aa5af !important; }

  /* ====================================================================
     Buttons
     ==================================================================== */
  /* primary green CTA keeps the brand fill */
  .ds-btn--primary {
    background-color: #3b8047 !important;
    color: #ffffff !important;
    border-color: #3b8047 !important;
  }
  .ds-btn--primary:hover {
    background-color: #4a9a58 !important;
    border-color: #4a9a58 !important;
  }
  /* the CONVERSION CTA ("Speichern" on a recipe, "Jetzt kostenlos testen") is
     CORAL #ff565d on the light site, NOT green — painting it with the brand
     green swapped the hue of the site's loudest call to action. Deepen the
     coral instead so the white label still clears 4.5:1. */
  .ds-btn--conversion {
    background-color: #cf444a !important;
    color: #ffffff !important;
    border-color: #cf444a !important;
  }
  .ds-btn--conversion:hover {
    background-color: #e05159 !important;
    border-color: #e05159 !important;
  }
  .ds-btn--primary .ds-btn__label, .ds-btn--conversion .ds-btn__label,
  .ds-btn--primary .ds-btn__icon, .ds-btn--conversion .ds-btn__icon,
  .ds-btn--primary .chefkoch-icons, .ds-btn--conversion .chefkoch-icons { color: #ffffff !important; }
  /* round icon buttons ship a white circle -> dark elevated circle */
  .ds-btn--round {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .ds-btn--round:hover { background-color: #2d333b !important; }
  /* the "merken" favourite button is a white circle holding a CORAL heart —
     only the circle goes dark; the heart keeps its red */
  .ds-btn--save {
    background-color: #21262d !important;
    color: #ff7a80 !important;
    border-color: #2d333b !important;
  }
  .ds-btn--save .ds-btn__icon, .ds-btn--save .chefkoch-icons { color: #ff7a80 !important; }
  .ds-btn--save:hover { background-color: #2d333b !important; }
  .ds-btn--save:hover .ds-btn__icon, .ds-btn--save:hover .chefkoch-icons { color: #ff9a9e !important; }
  /* "ghost" buttons ("Planen"/"Drucken"/"Folgen", slider arrows, action menus)
     are a white fill with a GREEN border and a GREEN label — keep the green */
  .ds-btn--secondary, .ds-btn--control, .ds-btn--action-menu {
    background-color: #1c2128 !important;
    color: #4cae5e !important;
    border-color: #3b8047 !important;
  }
  .ds-btn--secondary .ds-btn__label, .ds-btn--control .ds-btn__label,
  .ds-btn--action-menu .ds-btn__label,
  .ds-btn--secondary .chefkoch-icons, .ds-btn--control .chefkoch-icons,
  .ds-btn--action-menu .chefkoch-icons { color: #4cae5e !important; }
  .ds-btn--secondary:hover, .ds-btn--control:hover, .ds-btn--action-menu:hover {
    background-color: #21262d !important;
    border-color: #6fd382 !important;
  }
  /* tertiary = a bare green text button (no fill natively); monochrome/close =
     a bare grey text button. Neither should grow a pill. */
  .ds-btn--tertiary {
    background-color: transparent !important;
    color: #4cae5e !important;
    border-color: transparent !important;
  }
  .ds-btn--tertiary .ds-btn__label, .ds-btn--tertiary .ds-btn__icon,
